def separate_paren_groups(paren_string: str) -> List[str]:
    def extract_groups(paren_string):
        groups = []
        group = ""
        in_group = False
        for char in paren_string:
            if char == '(':
                in_group = True
            elif char == ')':
                in_group = False
                groups.append(group)
                group = ""
            elif in_group:
                group += char
        return groups

    def remove_spaces(groups):
        return [group.replace(" ", "") for group in groups]

    def is_balanced(group):
        stack = []
        for char in group:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack or stack.pop() != '(':
                    return False
        return not stack

    extracted_groups = extract_groups(paren_string)
    cleaned_groups = remove_spaces(extracted_groups)
    balanced_groups = [group for group in cleaned_groups if is_balanced(group)]

    return balanced_groups

